//! The marks of the AI providers whose usage Glance shows, each as its maker draws it: from @lobehub/icons-static-svg
//! 1.95.0 (MIT License, Copyright (c) 2023 LobeHub), as Folio collected them. Each mark is its owner's trademark,
//! shown to say whose usage a figure is. A mark drawn in one colour takes the colour of the text it is with (so is
//! Kimi's K, white in the original, unseen on a light ground).
//!
//! Generated from those files: their paths as they are, on a 24-unit grid.

/// A provider's mark.
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub enum Mark {
    /// Claude's.
    Claude,
    /// OpenAI's.
    OpenAi,
    /// Kimi's.
    Kimi,
    /// Z.ai (Zhipu)'s.
    Zai,
    /// MiniMax's.
    MiniMax,
    /// DeepSeek's.
    DeepSeek,
    /// OpenRouter's.
    OpenRouter,
    /// Qwen's.
    Qwen,
    /// Moonshot's.
    Moonshot,
}

/// How a layer of a mark is filled.
#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Paint {
    /// In its own colour.
    Own(u32),
    /// In the colour of the text beside it.
    Text,
    /// From one colour (and how opaque) to another, along the line `from` to `to` across its box (0 to 1 of its width
    /// and height).
    Across { from: (f32, f32), to: (f32, f32), colours: ((u32, f32), (u32, f32)) },
}

/// One path of a mark: its data (SVG's), how it is filled, and whether by the even-odd rule (else non-zero).
#[derive(Clone, Copy, PartialEq, Debug)]
pub struct Layer {
    pub data: &'static str,
    pub paint: Paint,
    pub even_odd: bool,
}

