#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_mark_reads_whole_on_its_grid() {
        for mark in [Mark::Claude, Mark::OpenAi, Mark::Kimi, Mark::Zai, Mark::MiniMax, Mark::DeepSeek, Mark::OpenRouter, Mark::Qwen, Mark::Moonshot] {
            for layer in mark.layers() {
                let figures = super::super::icons::parse(layer.data);
                assert!(!figures.is_empty(), "{mark:?}");
                // (Every segment's end read: a command not read would end the figures early, off the mark.)
                let ends = figures.iter().flat_map(|figure| std::iter::once(figure.start).chain(figure.segments.iter().map(|segment| match *segment {
                    super::super::icons::Segment::Line(to) | super::super::icons::Segment::Cubic(_, _, to) | super::super::icons::Segment::Arc { to, .. } => to,
                })));
                for (x, y) in ends {
                    assert!((-0.5..=24.5).contains(&x) && (-0.5..=24.5).contains(&y), "{mark:?} ({x}, {y})");
                }
            }
        }
    }
}
